<script setup lang="ts">
import Swal from 'sweetalert2'
import type { AssessmentCalculationRun, AssessmentOfferingSummary, GradingSchemeSummary, ResultBatchSummary } from '@emhare/portal-shell/types/assessment'
definePageMeta({layout:'dashboard'})
const api=useEmhareApi();const toast=useToast();const{showError}=useEmhareConfirm();const batches=ref<ResultBatchSummary[]>([]);const calculations=ref<AssessmentCalculationRun[]>([]);const offerings=ref<AssessmentOfferingSummary[]>([]);const grading=ref<GradingSchemeSummary[]>([]);const loading=ref(false);const saving=ref(false);const modalOpen=ref(false);const form=reactive({calculationRunId:'',gradingSchemeId:''})
const academicPeriodContext=useAcademicPeriodContext()
const publishableCalculations=computed(()=>calculations.value.filter(run=>run.status==='COMPLETED'&&run.incompleteResultCount===0&&run.publicationEvidenceAvailable&&!batches.value.some(batch=>batch.calculationRunId===run.id)))
const calculationItems=computed(()=>publishableCalculations.value.map(run=>({label:`${offering(run.offeringId)?.moduleCode??'Module'} · ${offering(run.offeringId)?.academicPeriodCode??''} · ${run.completeResultCount} complete · ${new Date(run.initiatedAt).toLocaleString()}`,value:run.id})))
const gradingItems=computed(()=>grading.value.filter(item=>item.status==='APPROVED').map(item=>({label:`${item.code} v${item.schemeVersion} · ${item.name}`,value:item.id})))
const queueCounts=computed(()=>({submitted:batches.value.filter(item=>item.status==='SUBMITTED').length,moderated:batches.value.filter(item=>item.status==='MODERATED').length,approved:batches.value.filter(item=>item.status==='APPROVED').length,published:batches.value.filter(item=>item.status==='PUBLISHED').length}))
function offering(id:string){return offerings.value.find(item=>item.id===id)}
onMounted(load)
watch(academicPeriodContext.selectedAcademicPeriodId,()=>void load())
async function load(){loading.value=true;try{await academicPeriodContext.ensureAcademicPeriods();const[batchResponse,calculationResponse,offeringResponse,gradingResponse]=await Promise.all([api.request<ResultBatchSummary[]>('/api/results/batches'),api.request<AssessmentCalculationRun[]>('/api/assessment-results/calculations'),api.request<AssessmentOfferingSummary[]>('/api/assessment-results/offerings'),api.request<GradingSchemeSummary[]>('/api/results/grading-schemes')]);offerings.value=offeringResponse.filter(offering=>academicPeriodContext.matchesAcademicPeriod(offering));const offeringIds=new Set(offerings.value.map(offering=>offering.id));batches.value=batchResponse.filter(batch=>academicPeriodContext.matchesAcademicPeriod(batch));calculations.value=calculationResponse.filter(calculation=>offeringIds.has(calculation.offeringId));grading.value=gradingResponse}catch(error){await showError('Result governance queue could not be loaded',api.errorMessage(error))}finally{loading.value=false}}
function openBatch(){form.calculationRunId='';form.gradingSchemeId='';modalOpen.value=true}
async function createBatch(){if(!form.calculationRunId||!form.gradingSchemeId)return;saving.value=true;try{await api.request('/api/results/batches',{method:'POST',body:form});modalOpen.value=false;await load();toast.add({title:'Draft result batch created',description:'Calculated results are ready for controlled submission.',color:'success'})}catch(error){await showError('Result batch could not be created',api.errorMessage(error))}finally{saving.value=false}}
function nextAction(batch:ResultBatchSummary){if(batch.status==='DRAFT')return{action:'submit',label:'Submit for moderation',title:'Submit result batch?'};if(batch.status==='SUBMITTED')return{action:'moderate',label:'Record moderation',title:'Moderate result batch?'};if(batch.status==='MODERATED')return{action:'approve',label:'Approve results',title:'Approve moderated results?'};if(batch.status==='APPROVED')return{action:'publish',label:'Publish results',title:'Publish approved results?'};return null}
function completedActionLabel(action:string){return{submit:'submitted',moderate:'moderated',approve:'approved',publish:'published'}[action]??'updated'}
async function move(batch:ResultBatchSummary){const next=nextAction(batch);if(!next)return;const result=await Swal.fire({title:next.title,text:next.action==='publish'?'Publication creates immutable student-facing results. Corrections require a governed amendment.':'The decision and actor are retained in the result lifecycle.',icon:next.action==='publish'?'warning':'question',input:'textarea',inputLabel:'Decision reason',inputPlaceholder:'Record evidence reviewed and authority for this decision.',showCancelButton:true,confirmButtonText:next.label,confirmButtonColor:'#006633',inputValidator:value=>value.trim()?undefined:'A decision reason is required.'});if(!result.isConfirmed||!result.value?.trim())return;try{await api.request(`/api/results/batches/${batch.id}/${next.action}`,{method:'POST',body:{expectedVersion:batch.version,reason:result.value.trim()}});await load();toast.add({title:`Result batch ${completedActionLabel(next.action)}`,description:batch.batchNumber,color:'success'})}catch(error){await showError('Result decision could not be recorded',api.errorMessage(error))}}
</script>
<template><UDashboardPanel><template #header><UDashboardNavbar title="Result board workflow"><template #leading><UDashboardSidebarCollapse/></template><template #right><UButton label="Create result batch" icon="i-lucide-file-plus-2" @click="openBatch"/><UButton label="Refresh" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="loading" @click="load"/></template></UDashboardNavbar></template><template #body><div class="space-y-5 p-4 sm:p-6"><UAlert color="primary" variant="soft" icon="i-lucide-shield-check" title="Four-eyes result release" description="Batches originate from immutable calculation evidence. Submitter, moderator, and approver separation is enforced before controlled publication."/><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-info">Moderation</p><p class="mt-2 text-2xl font-semibold">{{queueCounts.submitted}}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-warning">Approval</p><p class="mt-2 text-2xl font-semibold">{{queueCounts.moderated}}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-primary">Publication</p><p class="mt-2 text-2xl font-semibold">{{queueCounts.approved}}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-success">Published</p><p class="mt-2 text-2xl font-semibold">{{queueCounts.published}}</p></UCard></section><EmharePaginatedCollection v-slot="{ items: paginatedBatches }" :items="batches"><div class="space-y-3"><UCard v-for="batch in paginatedBatches" :key="batch.id" :ui="{body:'p-4'}"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-medium text-primary">{{batch.batchNumber}}</p><h2 class="mt-1 font-semibold">{{batch.moduleCode}} · {{batch.moduleName}}</h2><p class="mt-1 text-sm text-muted">{{batch.academicPeriodCode}} · {{batch.resultCount}} result{{batch.resultCount===1?'':'s'}}</p></div><UBadge :label="batch.status" :color="batch.status==='PUBLISHED'?'success':batch.status==='APPROVED'?'primary':batch.status==='MODERATED'?'warning':'neutral'" variant="subtle"/></div><EmharePaginatedCollection v-slot="{ items: paginatedResults }" :items="batch.results"><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[620px] text-sm"><thead class="text-left text-xs uppercase text-muted"><tr><th class="py-2">Student</th><th>Coursework</th><th>Exam</th><th>Final</th><th>Grade</th><th>Remark</th></tr></thead><tbody><tr v-for="result in paginatedResults" :key="result.id" class="border-t border-muted"><td class="py-2 font-medium">{{result.studentNumber}}</td><td>{{result.courseworkMark}}</td><td>{{result.examinationMark}}</td><td class="font-semibold">{{result.finalMark}}</td><td>{{result.grade}}</td><td>{{result.remark}}</td></tr></tbody></table></div></EmharePaginatedCollection><div class="mt-4 flex flex-wrap items-center justify-between gap-3"><p class="text-xs text-muted">{{batch.statusReason}}</p><UButton v-if="nextAction(batch)" :label="nextAction(batch)?.label" icon="i-lucide-arrow-right" @click="move(batch)"/></div></UCard></div></EmharePaginatedCollection><UAlert v-if="!loading&&!batches.length" color="neutral" variant="soft" title="No result batches" description="Run a complete assessment calculation and approve a grading scheme first."/></div></template></UDashboardPanel><EmhareRecordDrawer v-model:open="modalOpen" title="Create result batch" description="Materialise results from exact calculation evidence"><template #body><div class="space-y-4"><UFormField label="Completed calculation"><USelect v-model="form.calculationRunId" :items="calculationItems" class="w-full" placeholder="Select calculation run"/></UFormField><UFormField label="Approved grading scheme"><USelect v-model="form.gradingSchemeId" :items="gradingItems" class="w-full" placeholder="Select grading scheme"/></UFormField><UAlert color="info" variant="soft" title="Evidence boundary" description="The selected calculation's submitted mark revisions and approved component rules are copied into immutable result evidence."/></div></template><template #footer><div class="flex w-full justify-end gap-2"><UButton label="Cancel" color="neutral" variant="outline" @click="modalOpen=false"/><EmhareGuidedActionButton label="Create draft batch" :loading="saving" guidance-title="Result batch evidence is incomplete" :guidance-instructions="[...(!form.calculationRunId ? ['Select a completed assessment calculation.'] : []), ...(!form.gradingSchemeId ? ['Select an approved grading scheme.'] : [])]" @click="createBatch"/></div></template></EmhareRecordDrawer></template>
